import json

routine_clock = Timer()
phase = "starting"
search_degrees = {}
activity_result = {
    "ok": False,
    "collected_blue_reported": False,
    "tag_0_approach_completed": False,
    "release_reported": False
}

def progress(value):
    global phase
    phase = value
    print("__VEXAIM_EVENT__" + json.dumps({"event": "progress", "phase": value}))

def check_deadline():
    if routine_clock.time(MSEC) >= 30000:
        raise RuntimeError("Routine deadline reached during " + phase)

def bounded_wait(duration_ms):
    began = routine_clock.time(MSEC)
    while routine_clock.time(MSEC) - began < duration_ms:
        check_deadline()
        wait(25, MSEC)

def finish_motion(limit_ms=3000, collected=None):
    began = routine_clock.time(MSEC)
    while not robot.is_stopped():
        check_deadline()
        if collected is not None and collected():
            robot.stop_all_movement()
            return True
        if routine_clock.time(MSEC) - began >= limit_ms:
            raise RuntimeError("Movement deadline reached during " + phase)
        wait(25, MSEC)
    check_deadline()
    return True

def approach(target, width, collected=None, move_speed=200):
    began = routine_clock.time(MSEC)
    last_seen = None
    previous = robot.inertial.get_rotation()
    key = str(target)
    search_degrees.setdefault(key, 0)
    while routine_clock.time(MSEC) - began < 10000:
        check_deadline()
        rotation = robot.inertial.get_rotation()
        search_degrees[key] += abs(rotation - previous)
        previous = rotation
        if search_degrees[key] >= 360:
            robot.stop_all_movement()
            raise RuntimeError("Search angular limit reached during " + phase)
        if collected is not None and collected():
            robot.stop_all_movement()
            return True
        objects = [o for o in robot.vision.get_data(target, 4) if o.exists]
        if objects:
            last_seen = routine_clock.time(MSEC)
            obj = max(objects, key=lambda o: o.width)
            if abs(obj.bearing) > 10:
                robot.turn(LEFT if obj.bearing < 0 else RIGHT, 90, DPS)
            elif obj.width >= width:
                robot.stop_all_movement()
                return True
            else:
                robot.move_at(obj.bearing, move_speed, MMPS)
        elif last_seen is None:
            robot.turn(RIGHT, 120, DPS)
        else:
            robot.stop_all_movement()
            if routine_clock.time(MSEC) - last_seen >= 600:
                raise RuntimeError("Target lost during " + phase)
        wait(50, MSEC)
    robot.stop_all_movement()
    raise RuntimeError("Target search timed out during " + phase)

try:
    robot.vision.model_detection(True)
    robot.vision.tag_detection(True)
    progress("collecting_blue")
    for attempt in range(2):
        check_deadline()
        if robot.has_blue_barrel():
            break
        if not approach(BLUE_BARREL, 90, robot.has_blue_barrel, 200):
            raise RuntimeError("Blue barrel approach failed")
        if not robot.has_blue_barrel():
            progress("contact")
            robot.move_for(200, 0, 200, MMPS, False)
            if not finish_motion(2000, robot.has_blue_barrel):
                raise RuntimeError("Contact movement failed")
            bounded_wait(100)
        if robot.has_blue_barrel():
            break
        if attempt == 0:
            progress("realigning")
            robot.move_for(50, 180, 150, MMPS, False)
            if not finish_motion():
                raise RuntimeError("Realignment movement failed")
            progress("collecting_blue_retry")
    if not robot.has_blue_barrel():
        raise RuntimeError("Blue barrel possession was not reported")
    activity_result["collected_blue_reported"] = True
    progress("finding_tag_0")
    if not approach(TAG0, 60, move_speed=150):
        raise RuntimeError("Tag 0 approach failed")
    activity_result["tag_0_approach_completed"] = True
    if not robot.has_blue_barrel():
        raise RuntimeError("Cargo lost before placement")
    progress("placing")
    check_deadline()
    robot.kicker.place()
    bounded_wait(300)
    robot.move_for(100, 180, 150, MMPS, False)
    if not finish_motion():
        raise RuntimeError("Placement backoff failed")
    if robot.has_blue_barrel():
        raise RuntimeError("Blue barrel release was not reported")
    activity_result["release_reported"] = True
    progress("complete")
    robot.led.on(ALL_LEDS, GREEN)
    robot.screen.show_emoji(Emoji.HAPPY, EmojiLook.LOOK_FORWARD)
    activity_result["ok"] = True
except Exception as error:
    activity_result["error"] = str(error)
    raise
finally:
    robot.stop_all_movement()
    activity_result["phase"] = phase
    activity_result["elapsed_ms"] = routine_clock.time(MSEC)
    print(json.dumps(activity_result))
